(() => {
 const registry=window.__CODEX_USAGE_MONITOR_MODULES__ ||= {};
 if(registry.fonts?.version==='1.2' || typeof FontFace!=='function' || !document.fonts)return;
 registry.fonts?.faces?.forEach(face=>document.fonts.delete(face));
 // Embedded binary sources avoid remote font requests and font-src URL policies.
 const sources={"MonitorSans":"","MonitorLora":"","MonitorBarlow":"","MonitorCaveat":"","MonitorWenkai":""};
 const faces=Object.entries(sources).map(([family,data])=>{
  const bytes=Uint8Array.from(atob(data),c=>c.charCodeAt(0));
  const face=new FontFace(family,bytes.buffer,{weight:'400',style:'normal'});
  document.fonts.add(face);return face;
 });
 const ready=Promise.allSettled(faces.map(face=>face.load())).then(results=>{
  registry.fonts.failed=results.some(result=>result.status==='rejected');
  window[registry.constants.STATE_KEY]?.ensure?.();return results;
 });
 registry.fonts={version:'1.2',faces,ready,failed:false};
})();
